def is_prime(n):
    """
    Check if a number n is prime.

    A prime number (or a prime) is a natural number greater than 1 that is not a product of two smaller positive integers.
    This means it can only be evenly divided by 1 and itself.

    Parameters:
    - n: The number to check for primality.

    Returns:
    - True if n is a prime number, False otherwise.
    """
    if n <= 1:
        return False
    elif n == 2:
        return True
    else:
        for i in range(2, int(n**0.5) + 1):
            if n % i == 0:
                return False
        return True

# Example usage and verification
