def fibonacci(n):
    """
    Calculate the n-th Fibonacci number.

    Parameters:
    n (int): The position in the Fibonacci sequence to calculate.

    Returns:
    int: The n-th Fibonacci number.
    """
    if n == 0:
        return 0
    elif n == 1:
        return 1
    else:
        a, b = 0, 1
